    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations / 4 + 1; nl++) {
        for (Index_type i = 0; i < 256; ++i) x[i] = 0.0;

#if defined(__riscv_vector)
        Index_type i = 0;
        while (i < LEN_1D) {
            size_t vl = __riscv_vsetvl_e32m1((size_t)(LEN_1D - i));
            vint32m1_t v = __riscv_vle32_v_i32m1((const int32_t *)&idx_list[i], vl);

            // Store to a stack buffer to keep the exact same per-element work.
            // This preserves the original scalar histogram update semantics.
            int32_t tmp[256];
            __riscv_vse32_v_i32m1(tmp, v, vl);

            for (size_t j = 0; j < vl; ++j) {
                x[tmp[j]] += 1.0;
            }

            i += (Index_type)vl;
        }
#else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            x[idx_list[i]] += 1.0;
        }
#endif

        dummy(x, NULL, NULL, NULL, NULL, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

